(function(){
var ST=window.ST,BA=ST.BA,esc=ST.esc,$=ST.$,staff=ST.staff,D=BA.D;if(!staff||!$('app'))return;
var tab='ov',q='',pf='',cf='';
function exc(){var s=BA.jget('ba3_exc',{}),open=0,done=0;(window.BA_EXC||[]).forEach(function(r){var st=(s[r.id]&&s[r.id].status)||r.status;if(st==='approved')done++;else open++});return {open:open,done:done}}
function render(){var bk=BA.bk(),pend=bk.filter(function(b){return b.status==='requested'}).length;
 $('app').innerHTML=ST.head('Admin console','Run the platform: customers, staff, listings, advocates, payments and the audit trail. Every action here is written to the audit log.')+ST.tabsHtml([['ov','Overview'],['us','Customers'],['sf','Staff'],['fo','Field operations'],['ls','Listings'],['lw','Advocates'],['pm','Payments'],['au','Audit log'],['cr','Home carousel'],['fd','Founder page'],['sy','Site settings']],tab)+'<div id="tb"></div>';
 $('tabs').onclick=function(e){var b=e.target.closest('button');if(b){tab=b.dataset.t;q='';pf='';cf='';render()}};
 ({ov:ov,us:us,sf:sf,fo:fo,ls:ls,lw:lw,pm:pm,au:au,sy:sy,cr:function(){window.ADM_CAR($('tb'))},fd:function(){window.ADM_FD($('tb'))}})[tab]()}
function ov(){var u=ST.users(),e=exc(),bk=BA.bk(),fv=Object.keys(BA.jget('ba3_fv',{})).length,un=BA.jget('ba3_unpub',[]).length;
 var tiles=[['Exception queue',e.open+' open',e.done+' approved this week','checker.html'],['Advocate requests',bk.filter(function(b){return b.status==='requested'}).length+' waiting','across all advocates','lawyer.html'],['Field visits',FV.flagged().length+' overdue',FV.counts(Object.keys(FV.asg()).map(function(k){return {a:FV.asg()[k]}}).filter(function(x){return !x.a.sub&&!x.a.fin})).urgent+' urgent · '+FV.queue().filter(function(q){return q.status==='submitted'}).length+' with checker',''],['Unpublished properties',un,'hidden from the public site','']];
 $('tb').innerHTML='<div class="kpis">'+ST.kpi('Registered users',ST.num(u.length*95),(u.filter(function(x){return x.plan!=='Free'}).length*95)+' paying')+ST.kpi('Live properties',BA.all().length,'Maker 75% · exceptions 25%')+ST.kpi('Suspended accounts',u.filter(function(x){return x.status==='suspended'}).length,'')+ST.kpi('Refunds issued',Object.keys(BA.jget('ba3_refunds',{})).length,'')+'</div>'+
 ST.panel('Operations at a glance','<div class="three">'+tiles.map(function(t){return '<div class="kpi"><small>'+t[0]+'</small><b style="font-size:26px">'+t[1]+'</b><span>'+t[2]+'</span>'+(t[3]?'<br><a href="'+t[3]+'" style="color:var(--rose);font-weight:700">Open →</a>':'')+'</div>'}).join('')+'</div>')+
 ST.panel('Field visit alerts',ST.table(['When','Alert'],FV.notifs('admin').slice(0,6).map(function(n){return '<tr><td style="white-space:nowrap">'+ST.ago(n.at)+'</td><td>'+(n.sev==='red'?'<span style="color:#A50E0E">●</span> ':'')+esc(n.text)+'</td></tr>'})),'<button class="btn out sm" onclick="document.querySelector(\'#tabs [data-t=fo]\').click()">Open field operations</button>')+
 ST.panel('Latest activity',ST.table(['When','Who','Action'],BA.jget('ba3_audit',[]).slice(-8).reverse().map(function(a){return '<tr><td>'+ST.ago(a.at)+'</td><td>'+esc(a.who)+' · '+esc(a.role)+'</td><td>'+esc(a.what)+'</td></tr>'})))}
function us(){var u=ST.users().filter(function(x){return(!q||(x.name+x.phone).toLowerCase().indexOf(q)>-1)&&(!pf||x.plan===pf)});
 $('tb').innerHTML=ST.panel('Customers ('+u.length+' in this sample)','<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px"><input id="q" class="cs" style="color:var(--ink);min-width:220px" placeholder="Search name or phone" value="'+esc(q)+'"><select id="pf" class="cs" style="color:var(--ink)"><option value="">All plans</option>'+['Free','Pro pack','Pro used up','Premium property','Pro + Premium property'].map(function(p){return '<option'+(pf===p?' selected':'')+'>'+p+'</option>'}).join('')+'</select></div>'+ST.table(['Customer','City','Plan','Unlocked','Joined','Status',''],u.slice(0,40).map(function(x){return '<tr><td><b>'+esc(x.name)+'</b><br><small style="color:var(--mute)">+91 '+x.phone.slice(0,2)+'••• •••'+x.phone.slice(-3)+'</small></td><td>'+esc(D.cities[x.city].label)+'</td><td>'+esc(x.plan)+'</td><td>'+x.unl+'</td><td>'+ST.dfmt(x.joined)+'</td><td>'+(x.status==='active'?ST.chip('Active','g'):ST.chip('Suspended','r'))+'</td><td style="white-space:nowrap"><button class="btn out sm" data-gift="'+x.id+'">+5 unlocks</button> <button class="btn out sm" data-sus="'+x.id+'">'+(x.status==='active'?'Suspend':'Reinstate')+'</button></td></tr>'})));
 $('q').oninput=function(){q=this.value.toLowerCase();var p=this.selectionStart;us();$('q').focus();$('q').setSelectionRange(p,p)};$('pf').onchange=function(){pf=this.value;us()};
 $('tb').onclick=function(e){var t=e.target.closest('button');if(!t)return;var d=t.dataset;
  if(d.sus){var x=ST.users().filter(function(y){return y.id===d.sus})[0],ns=x.status==='active'?'suspended':'active';ST.setUser(d.sus,{status:ns});ST.log((ns==='suspended'?'Suspended ':'Reinstated ')+x.name);BA.toast(x.name+': '+ns);us()}
  else if(d.gift){var x2=ST.users().filter(function(y){return y.id===d.gift})[0];if(x2.live){var c=BA.cr();c.pk=c.pk||[];c.pk.push({cat:'res',size:5,left:5,at:Date.now()});c.left+=5;c.packs=(c.packs||0)+1;BA.saveCr(c)}else{var pl=x2.plan==='Free'||x2.plan==='Pro used up'?'Pro pack':x2.plan;ST.setUser(d.gift,{plan:pl})}ST.log('Granted 5 unlocks to '+x2.name);BA.toast('5 unlocks granted to '+x2.name);us()}}}
function sf(){window.ADM_STAFF($('tb'),render)}
function fo(){window.ADM_FIELD($('tb'),render)}
function ls(){var un=BA.jget('ba3_unpub',[]),ex=BA.jget('ba3_exc',{}),L=BA.allRaw().filter(function(p){return(!cf||p.city===cf)&&(!q||(p.title+p.id+p.bank).toLowerCase().indexOf(q)>-1)});
 $('tb').innerHTML=ST.panel('Listings ('+L.length+')','<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px"><input id="q" class="cs" style="color:var(--ink);min-width:240px" placeholder="Search property, title or lender" value="'+esc(q)+'"><select id="cf" class="cs" style="color:var(--ink)"><option value="">All cities</option>'+BA.ck.map(function(c){return '<option value="'+c+'"'+(cf===c?' selected':'')+'>'+esc(D.cities[c].label)+'</option>'}).join('')+'</select></div>'+ST.table(['Lot','Property','Lender','Reserve','Source','Status',''],L.slice(0,40).map(function(p){var off=un.indexOf(p.id)>-1;return '<tr><td>'+p.id+'</td><td style="max-width:260px">'+esc(p.short)+' · '+esc(p.loc)+'<br><small style="color:var(--mute)">'+esc(D.cities[p.city].label)+(p.premium?' · Premium':'')+'</small></td><td>'+esc(p.bank)+'</td><td>'+BA.inr(p.reserve)+'</td><td>'+(p.exception?'Checker':'Maker')+'</td><td>'+(off?ST.chip('Unpublished','r'):ST.chip('Live','g'))+'</td><td><button class="btn out sm" data-docs="'+p.id+'">Documents ('+(3+(BA.jget('ba3_docs',{})[p.id]||[]).length)+')</button> <button class="btn out sm" data-up="'+p.id+'">'+(off?'Republish':'Unpublish')+'</button> <a class="btn out sm" href="property.html?id='+p.id+'&sv=1" target="_blank">View</a></td></tr>'})));
 $('q').oninput=function(){q=this.value.toLowerCase();var p=this.selectionStart;ls();$('q').focus();$('q').setSelectionRange(p,p)};$('cf').onchange=function(){cf=this.value;ls()};
 $('tb').onclick=function(e){var dc=e.target.closest('[data-docs]');if(dc){docs(dc.dataset.docs);return}var t=e.target.closest('[data-up]');if(!t)return;var a=BA.jget('ba3_unpub',[]),i=a.indexOf(t.dataset.up);if(i>-1)a.splice(i,1);else a.push(t.dataset.up);BA.jset('ba3_unpub',a);ST.log((i>-1?'Republished ':'Unpublished ')+t.dataset.up);BA.toast(i>-1?'Republished':'Hidden from the public site');ls()}}
function docs(id){var p=BA.allRaw().filter(function(x){return x.id===id})[0],list=ST.docsFor(p);
 BA.box('<h3>Documents for '+esc(p.short)+' · '+id+'</h3><p style="color:var(--mute)">Advocates see these when they open a booking about this property.</p>'+list.map(function(d){return '<div class="doc"><span><b>'+esc(d.n)+'</b><br><small style="color:var(--mute)">'+esc(d.by)+(d.at?' · '+esc(d.at):'')+'</small></span></div>'}).join('')+'<div class="form" style="max-width:none;margin-top:14px"><label>Add a document<input id="dn" placeholder="e.g. Encumbrance certificate, 13 years"></label><label>File (optional, up to 400 KB)<input id="df" type="file" accept=".pdf,image/*"></label><button class="btn" id="dg">Attach to this property</button><div id="de" class="ok" style="background:#FFE9EE;color:#9B1C47" hidden></div></div>');
 $('dg').onclick=function(){var n=$('dn').value.trim(),f=$('df').files[0];if(!n){$('de').hidden=false;$('de').textContent='Give the document a name.';return}
  function save(data){var all=BA.jget('ba3_docs',{});(all[id]=all[id]||[]).push({n:n,by:staff.name+' (Admin)',at:ST.dfmt(Date.now()),data:data||'',size:f?f.size:0});BA.jset('ba3_docs',all);ST.log('Attached document "'+n+'" to '+id);BA.closeBox();BA.toast('Document attached');ls()}
  if(f){if(f.size>400000){$('de').hidden=false;$('de').textContent='That file is over 400 KB. Attach a smaller one.';return}var r=new FileReader();r.onload=function(){save(r.result)};r.readAsDataURL(f)}else save('')}}
function lw(){var apps=BA.jget('ba3_lapps',null);if(!apps){apps=[{id:'A1',name:'Adv. G. Prakash',court:'Madras High Court',yrs:'9 yrs',focus:'Property and DRT matters',st:'pending'},{id:'A2',name:'Adv. Nandini Rao',court:'Telangana High Court',yrs:'14 yrs',focus:'SARFAESI',st:'pending'},{id:'A3',name:'Adv. M. Joseph',court:'Kerala High Court',yrs:'6 yrs',focus:'Land records',st:'pending'}];BA.jset('ba3_lapps',apps)}
 var pay=BA.jget('ba3_pay',{}),by={};BA.bk().filter(function(b){return b.status==='completed'&&!b.paid&&!pay[b.id]}).forEach(function(b){by[b.lawyer]=(by[b.lawyer]||0)+Math.round(b.fee*.8)});
 $('tb').innerHTML=ST.panel('Empanelment applications',ST.table(['Advocate','Court','Experience','Focus','Status',''],apps.map(function(a){return '<tr><td><b>'+esc(a.name)+'</b></td><td>'+esc(a.court)+'</td><td>'+a.yrs+'</td><td>'+esc(a.focus)+'</td><td>'+(a.st==='pending'?ST.chip('Pending','a'):a.st==='approved'?ST.chip('Approved','g'):ST.chip('Rejected','r'))+'</td><td>'+(a.st==='pending'?'<button class="btn sm" data-ap="'+a.id+'">Approve</button> <button class="btn out sm" data-rj="'+a.id+'">Reject</button>':'')+'</td></tr>'})))+
 ST.panel('Payouts due to advocates',ST.table(['Advocate','Pending payout',''],Object.keys(by).map(function(k){return '<tr><td><b>'+esc(k)+'</b></td><td>'+ST.rs(by[k])+'</td><td><button class="btn sm" data-pay="'+esc(k)+'">Release payout</button></td></tr>'})));
 $('tb').onclick=function(e){var t=e.target.closest('button');if(!t)return;var d=t.dataset;
  if(d.ap||d.rj){apps.forEach(function(a){if(a.id===(d.ap||d.rj))a.st=d.ap?'approved':'rejected'});BA.jset('ba3_lapps',apps);ST.log((d.ap?'Approved ':'Rejected ')+'advocate application '+(d.ap||d.rj));lw()}
  else if(d.pay){var P=BA.jget('ba3_pay',{});BA.bk().forEach(function(b){if(b.lawyer===d.pay&&b.status==='completed')P[b.id]=1});BA.jset('ba3_pay',P);ST.log('Released payout to '+d.pay);BA.toast('Payout released (demo)');lw()}}}
function pm(){var L=ST.ledger(),tot=L.filter(function(p){return !p.refunded}).reduce(function(a,p){return a+p.amt},0);
 $('tb').innerHTML='<div class="kpis">'+ST.kpi('Collected (sample)',ST.rs(tot),'Net of refunds')+ST.kpi('Payments',L.length,'')+ST.kpi('Refunded',L.filter(function(p){return p.refunded}).length,'')+ST.kpi('Live from this browser',L.filter(function(p){return p.live}).length+' ●','')+'</div>'+ST.panel('Payments and refunds',ST.table(['Ref','When','Customer','Item','Amount','',''],L.slice(0,40).map(function(p){return '<tr><td>'+p.id+'</td><td>'+ST.dfmt(p.at)+'</td><td>'+esc(p.who)+'</td><td>'+esc(p.what)+'</td><td>'+(p.refunded?'<s>'+ST.rs(p.amt)+'</s>':ST.rs(p.amt))+'</td><td>'+(p.refunded?ST.chip('Refunded','n'):'')+'</td><td>'+(p.refunded?'':'<button class="btn out sm" data-rf="'+p.id+'">Refund</button>')+'</td></tr>'})),'<button class="btn out sm" id="pcsv">Download CSV</button>');
 $('pcsv').onclick=function(){ST.csv('payments.csv',[['Ref','Date','Customer','Item','Amount','Refunded']].concat(L.map(function(p){return [p.id,new Date(p.at).toISOString().slice(0,10),p.who,p.what,p.amt,p.refunded?'yes':'no']})))};
 $('tb').onclick=function(e){var t=e.target.closest('[data-rf]');if(!t)return;var r=BA.jget('ba3_refunds',{});r[t.dataset.rf]=1;BA.jset('ba3_refunds',r);ST.log('Refunded payment '+t.dataset.rf);BA.toast('Refund recorded (demo)');pm()}}
function au(){var A=BA.jget('ba3_audit',[]).map(function(a){return {at:a.at,who:a.who,role:a.role,what:a.what}}),ex=BA.jget('ba3_exc',{});
 Object.keys(ex).forEach(function(id){(ex[id].audit||[]).forEach(function(a){A.push({at:0,when:a.when,who:a.who,role:'Checker',what:a.what+' · '+id})})});
 var rows=A.sort(function(a,b){return b.at-a.at}).filter(function(a){return !q||(a.who+a.what+a.role).toLowerCase().indexOf(q)>-1}).slice(0,80);
 $('tb').innerHTML=ST.panel('Audit log','<input id="q" class="cs" style="color:var(--ink);min-width:260px;margin-bottom:12px" placeholder="Filter by person or action" value="'+esc(q)+'">'+ST.table(['When','Who','Role','Action'],rows.map(function(a){return '<tr><td>'+(a.at?ST.ago(a.at):esc(a.when||''))+'</td><td>'+esc(a.who)+'</td><td>'+esc(a.role)+'</td><td>'+esc(a.what)+'</td></tr>'})));
 $('q').oninput=function(){q=this.value.toLowerCase();var p=this.selectionStart;au();$('q').focus();$('q').setSelectionRange(p,p)}}
function sy(){var f=BA.jget('ba3_flags',{banner:'',maker:true,chat:true});
 $('tb').innerHTML=ST.panel('Site settings','<div class="tg"><span><b>Maker auto-publish</b><br><small style="color:var(--mute)">When off, every property goes to the checker queue.</small></span><input type="checkbox" id="fm" '+(f.maker?'checked':'')+'></div><div class="tg"><span><b>Chat widget</b><br><small style="color:var(--mute)">Show “Chat with us” to customers.</small></span><input type="checkbox" id="fc" '+(f.chat?'checked':'')+'></div><label class="form" style="max-width:none;margin-top:16px">Site-wide notice <small style="color:var(--mute)">shown above the header for every visitor. Leave empty for none.</small><input id="fb" value="'+esc(f.banner)+'" placeholder="Scheduled maintenance on Sunday, 2 to 3 am"></label><button class="btn" id="fs" style="margin-top:14px">Save settings</button>');
 $('fs').onclick=function(){var n={banner:$('fb').value.trim(),maker:$('fm').checked,chat:$('fc').checked};BA.jset('ba3_flags',n);BA.jset('ba3_banner',n.banner);ST.log('Changed site settings');BA.toast('Saved. Open the public site to see the notice.')}}
render();
})();
